WITH src AS (SELECT *, ADD_MONTHS(signup_date, 6) AS signup_date_plus_months FROM customers WHERE age IS NOT NULL AND is_active), summary AS (SELECT city, DATE_TRUNC('MONTH', signup_date) AS signup_month, MIN(signup_date) AS first_signup_date, MAX(age) - MIN(age) AS age_range FROM src GROUP BY city, DATE_TRUNC('MONTH', signup_date)) SELECT * FROM summary WHERE age_range < 71 ORDER BY signup_month
